const c = $('Confirm Booking in Supabase').first().json;
const adv = $('Create Advance Link').first().json || {};
const full = $('Create Full Link').first().json || {};
const n = $('Normalize Request').first().json.summary || {};
const total = Math.round(Number(n.total || n.totalMax || 0));
const payment = {};
const links = [];
if (adv.short_url) { payment.advance = { amount: Math.round(total * 0.3), url: adv.short_url }; links.push({ kind: 'advance', amount: payment.advance.amount, id: adv.id, short_url: adv.short_url }); }
if (full.short_url) { payment.full = { amount: total, url: full.short_url }; links.push({ kind: 'full', amount: total, id: full.id, short_url: full.short_url }); }
return [{ json: { p_code: c.bookingId, p_links: links, response: { ...c, total, payment } } }];

const r = $input.first().json || {};
const links = r.links || [];
if (!links.length) return [{ json: { rzp_link_id: 'none' } }];
return links.map(l => ({ json: { rzp_link_id: l.rzp_link_id, kind: l.kind } }));

const paid = [];
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.status === 'paid' && j.id) paid.push({ rzp_link_id: j.id, paid: true });
}
return [{ json: { p_code: $('Normalize Request').first().json.bookingId, p_paid: paid } }];
